exercises.solution:
using System.Threading.Channels;
using System.Threading.Tasks;

var ch = Channel.CreateUnbounded<string>();
var worker = Task.Run(async () =>
{
    await ch.Writer.WriteAsync("ping");
    ch.Writer.Complete();
});
Console.WriteLine(await ch.Reader.ReadAsync());
await worker;

using System.Threading.Channels;

