exercises.starter_code:
using System.Threading;
using System.Threading.Channels;
using System.Threading.Tasks;

// Task.Delay(10) inside worker

exercises.solution:
using System.Threading.Channels;
using System.Threading.Tasks;

var ch = Channel.CreateUnbounded<string>();
var worker = Task.Run(async () =>
{
    await Task.Delay(10);
    await ch.Writer.WriteAsync("from ch1");
    ch.Writer.Complete();
});
Console.Write(await ch.Reader.ReadAsync());
await worker;

exercises.starter_code:
using System.Threading.Channels;
using System.Threading.Tasks;

// foreach await or while TryRead

exercises.solution:
using System.Threading.Channels;
using System.Threading.Tasks;

var ch = Channel.CreateUnbounded<int>();
var producer = Task.Run(async () =>
{
    foreach (var n in new[] { 1, 2, 3 })
        await ch.Writer.WriteAsync(n);
    ch.Writer.Complete();
});
await foreach (var n in ch.Reader.ReadAllAsync())
    Console.WriteLine(n);
await producer;

exercises.starter_code:
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

// ConcurrentBag<string> or lock + List

exercises.solution:
using System.Collections.Generic;
using System.Threading.Tasks;

var list = new List<string>();
var gate = new object();
var a = Task.Run(() =>
{
    lock (gate) { list.Add("hello"); }
});
var b = Task.Run(() =>
{
    lock (gate) { list.Add("world"); }
});
await Task.WhenAll(a, b);
list.Sort();
foreach (var s in list)
    Console.WriteLine(s);

using System.Threading.Tasks;

for (var i = 1; i <= 3; i++)
{
    var j = i;
    Task.Run(() => Console.WriteLine(j)).Wait();
}
Console.WriteLine("done");
